/* 左余白いっぱいにシームレス拡大・縮小しつつ、右のキャラの顔と窓の高さが揃う上寄り配置にする。
   幅 = 左余白 (50% - 本文幅/2) から左右の小さな余白を引いた値（高さが画面からはみ出さない上限でクランプ）。
   会話欄自身の background に載せることで、::after のすりガラス帯より後ろに回り、狭い窓でも本文を邪魔しない。 */
[data-workspace-area="conversation"] {
  --left-scene-max-w: calc((100dvh - 5rem) * 6 / 11);
  --left-scene-w: clamp(180px, calc(50% - var(--chat-content-max-width, 46rem) / 2 - 1.5rem), var(--left-scene-max-w));
  background-image: var(--left-books), var(--left-window-frame), var(--left-sky);
  background-repeat: no-repeat;
  background-size: var(--left-scene-w) auto;
  background-position-x: max(0.75rem, calc(25% - (var(--chat-content-max-width, 46rem) + var(--left-scene-max-w)) / 4));
  background-position-y: clamp(1.5rem, 6vh, 4rem);
}

/* === スレッド詳細カードを左下に配置（右側のキャラの顔を隠さない） === */
[data-thread-details-panel="inline"] {
  right: auto !important;
  top: auto !important;
  left: 1rem !important;
  bottom: 1rem !important;
  max-height: min(46dvh, calc(100% - 12rem)) !important;
  max-width: max(220px, calc(50% - var(--chat-content-max-width, 46rem) / 2 - 2rem)) !important;
}
